// Anatomy of Flowering Plants - Question Bank
// Format follows the same schema used across the practice app:
// { id, type, question, options, correctIndex, explanation, difficulty }
// type: 'mcq' | 'assertion' | 'matching' | 'statement' | 'count'

export const ANATOMY_FLOWERING_PLANTS = [

  // ============ THE TISSUE SYSTEM: MERISTEMATIC TISSUES ============
  { id: 'aofp-1', type: 'mcq', question: 'A group of cells that are similar in origin and perform a specific function together is called a:', options: ['Organ', 'Tissue', 'Tissue system', 'Cell line'], correctIndex: 1, explanation: 'A tissue is defined as a group of cells having a common origin and usually performing a common function.', difficulty: 'easy' },
  { id: 'aofp-2', type: 'mcq', question: 'Plant tissues are broadly classified into two main types based on the dividing capacity of cells:', options: ['Simple and complex tissues', 'Meristematic and permanent tissues', 'Vascular and non-vascular tissues', 'Epidermal and ground tissues'], correctIndex: 1, explanation: 'Based on whether cells divide or not, plant tissues are classified as meristematic (dividing) and permanent (non-dividing, differentiated) tissues.', difficulty: 'easy' },
  { id: 'aofp-3', type: 'mcq', question: 'Meristematic tissues located at the tips of roots and shoots, responsible for increase in length, are called:', options: ['Lateral meristems', 'Intercalary meristems', 'Apical meristems', 'Secondary meristems'], correctIndex: 2, explanation: 'Apical meristems are present at the growing tips of stems and roots and cause an increase in the length of the plant, also called primary growth.', difficulty: 'easy' },
  { id: 'aofp-4', type: 'mcq', question: 'The meristem found at the base of the leaf or internode, as in grasses, which helps restore parts removed by grazing, is called:', options: ['Apical meristem', 'Intercalary meristem', 'Lateral meristem', 'Ground meristem'], correctIndex: 1, explanation: 'Intercalary meristem occurs between mature tissues, e.g., at the base of leaves or internodes in grasses, and helps regenerate cut/grazed parts.', difficulty: 'medium' },
  { id: 'aofp-5', type: 'mcq', question: 'Vascular cambium and cork cambium are examples of which type of meristem, responsible for increase in girth of the plant?', options: ['Apical meristem', 'Intercalary meristem', 'Lateral meristem', 'Primary meristem'], correctIndex: 2, explanation: 'Lateral meristems (vascular cambium and cork cambium) occur in the peripheral part of stems and roots, causing an increase in girth (secondary growth).', difficulty: 'medium' },
  { id: 'aofp-6', type: 'mcq', question: 'Based on the plane of cell division, meristems that divide in one plane and increase the length of the organ are called:', options: ['Mass meristem', 'Rib/File meristem', 'Plate meristem', 'Residual meristem'], correctIndex: 1, explanation: 'Rib or file meristem divides in one plane only and contributes to an increase in the length of the organ.', difficulty: 'hard' },
  { id: 'aofp-7', type: 'mcq', question: 'The cells of the apical meristem are characteristically:', options: ['Thick-walled and dead', 'Small, densely cytoplasmic and with prominent nuclei, but without vacuoles', 'Large and highly vacuolated', 'Lignified and non-dividing'], correctIndex: 1, explanation: 'Meristematic cells are usually spherical, oval or polygonal, thin-walled, with a large nucleus and dense cytoplasm; they generally lack vacuoles.', difficulty: 'medium' },

  // ============ PERMANENT TISSUES: SIMPLE TISSUES ============
  { id: 'aofp-8', type: 'mcq', question: 'Cells that have lost the capacity to divide and have attained a permanent shape, size and function are termed:', options: ['Meristematic cells', 'Permanent cells', 'Totipotent cells', 'Stem cells'], correctIndex: 1, explanation: 'Cells of meristematic tissue take up a specific role, lose the ability to divide, and become permanent (differentiated) tissue.', difficulty: 'easy' },
  { id: 'aofp-9', type: 'mcq', question: 'A simple tissue composed of living cells with thin cellulose walls, having intercellular spaces, and forming the bulk of the plant body, is called:', options: ['Parenchyma', 'Collenchyma', 'Sclerenchyma', 'Xylem'], correctIndex: 0, explanation: 'Parenchyma consists of relatively unspecialised, living cells with thin cell walls; it may perform photosynthesis (chlorenchyma) or storage (aerenchyma in aquatic plants).', difficulty: 'easy' },
  { id: 'aofp-10', type: 'mcq', question: 'Parenchyma cells with large air cavities to give buoyancy to plants growing in water are known as:', options: ['Chlorenchyma', 'Aerenchyma', 'Sclerenchyma', 'Collenchyma'], correctIndex: 1, explanation: 'In aquatic plants, parenchyma cells have large air cavities called aerenchyma that help the plant float.', difficulty: 'medium' },
  { id: 'aofp-11', type: 'mcq', question: 'A living mechanical tissue found in dicot stems and petioles below the epidermis, characterised by irregular wall thickening at the corners and providing flexibility, is:', options: ['Parenchyma', 'Collenchyma', 'Sclerenchyma', 'Xylem parenchyma'], correctIndex: 1, explanation: 'Collenchyma provides mechanical support to young plant parts; it has cells with irregular thickening of cellulose, hemicellulose and pectin at the corners, and provides flexibility without breaking.', difficulty: 'medium' },
  { id: 'aofp-12', type: 'mcq', question: 'Sclerenchyma consists of long, narrow, thick-walled and dead cells whose walls are impregnated with:', options: ['Cellulose only', 'Lignin', 'Suberin', 'Pectin'], correctIndex: 1, explanation: 'Sclerenchymatous cells are dead, with thick, lignified walls, providing mechanical strength; they occur as fibres or sclereids.', difficulty: 'medium' },
  { id: 'aofp-13', type: 'mcq', question: 'Long, narrow, elongated sclerenchymatous cells occurring in groups as fibres are contrasted with which other type of sclerenchyma cells?', options: ['Trichomes', 'Sclereids (short, irregular in shape)', 'Tracheids', 'Companion cells'], correctIndex: 1, explanation: 'Sclerenchyma has two forms: fibres (elongated cells) and sclereids (sclereids/stone cells — short, irregularly shaped, highly thickened cells), e.g., in the hard covering of nuts and pulp of guava/pear.', difficulty: 'medium' },
  { id: 'aofp-14', type: 'assertion', question: 'Assertion (A): Collenchyma allows young stems and petioles to bend without breaking.\nReason (R): Collenchyma cells are living and possess uneven wall thickening due to deposition of cellulose, hemicellulose and pectin, giving both mechanical support and flexibility.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The living nature and uneven, flexible wall thickening of collenchyma cells directly explains their role in providing mechanical strength while allowing bending.', difficulty: 'medium' },

  // ============ PERMANENT TISSUES: COMPLEX TISSUES (XYLEM & PHLOEM) ============
  { id: 'aofp-15', type: 'mcq', question: 'Xylem and phloem are together referred to as complex tissues because they are:', options: ['Made up of only one type of cell', 'Made up of more than one type of cell, all working together as a unit', 'Present only in roots', 'Composed exclusively of dead cells'], correctIndex: 1, explanation: 'Complex tissues are made of more than one type of cell that coordinate to perform a common function, unlike simple tissues.', difficulty: 'easy' },
  { id: 'aofp-16', type: 'mcq', question: 'The primary function of xylem tissue is:', options: ['Conduction of water and minerals', 'Conduction of food (photosynthates)', 'Gaseous exchange', 'Cell division'], correctIndex: 0, explanation: 'Xylem is a complex, conducting tissue that mainly conducts water and mineral nutrients from roots to other parts, and also provides mechanical strength.', difficulty: 'easy' },
  { id: 'aofp-17', type: 'mcq', question: 'Which of the following is NOT a component of xylem tissue?', options: ['Tracheids', 'Vessels', 'Sieve tubes', 'Xylem fibres'], correctIndex: 2, explanation: 'Sieve tubes are a component of phloem, not xylem. Xylem consists of tracheids, vessels, xylem fibres and xylem parenchyma.', difficulty: 'easy' },
  { id: 'aofp-18', type: 'mcq', question: 'Elongated, tube-like xylem cells with thick, lignified walls and tapering ends, having no perforations and conducting water through pits, are:', options: ['Vessels', 'Tracheids', 'Sieve tubes', 'Companion cells'], correctIndex: 1, explanation: 'Tracheids are elongated, tube-like cells with tapering ends; they lack perforations and water passes through pits from cell to cell.', difficulty: 'medium' },
  { id: 'aofp-19', type: 'mcq', question: 'Vessels differ from tracheids in that vessels are:', options: ['Long cylindrical tube-like structures made of vessel members joined end to end, with perforations, allowing efficient water conduction', 'Living cells with dense cytoplasm', 'Present only in gymnosperms', 'Devoid of lignin in their walls'], correctIndex: 0, explanation: 'A vessel is a long cylindrical tube-like structure made up of many vessel members (elements) that has perforated walls, allowing efficient long-distance water transport; vessels are characteristic of angiosperms.', difficulty: 'medium' },
  { id: 'aofp-20', type: 'mcq', question: 'Xylem parenchyma cells are unique among xylem components because they are:', options: ['Dead and lignified', 'Living, and can store food materials and allow radial conduction of water', 'Devoid of a nucleus', 'Found only in phloem'], correctIndex: 1, explanation: 'Unlike other xylary elements, xylem parenchyma cells are living, store food (starch, fat) and help in radial conduction of water.', difficulty: 'medium' },
  { id: 'aofp-21', type: 'mcq', question: 'Which of the following statements about xylem formed during primary growth is correct?', options: ['Protoxylem forms first, followed by metaxylem, and both are called primary xylem', 'Metaxylem always forms before protoxylem', 'Primary xylem is formed only during secondary growth', 'Protoxylem and metaxylem are the same tissue'], correctIndex: 0, explanation: 'The first-formed primary xylem elements are called protoxylem, and the later-formed ones are called metaxylem.', difficulty: 'medium' },
  { id: 'aofp-22', type: 'mcq', question: 'When the protoxylem lies towards the centre (pith) and the metaxylem lies towards the periphery, the xylem arrangement is called:', options: ['Exarch', 'Endarch', 'Mesarch', 'Centrarch'], correctIndex: 1, explanation: 'In endarch xylem (typical of stems), protoxylem is towards the centre and metaxylem is towards the periphery.', difficulty: 'hard' },
  { id: 'aofp-23', type: 'mcq', question: 'When protoxylem lies towards the periphery and metaxylem lies towards the centre, as typically seen in roots, the xylem arrangement is called:', options: ['Exarch', 'Endarch', 'Mesarch', 'Radial'], correctIndex: 0, explanation: 'In exarch xylem (typical of roots), protoxylem lies towards the periphery and metaxylem lies towards the centre.', difficulty: 'hard' },
  { id: 'aofp-24', type: 'mcq', question: 'The primary function of phloem tissue is:', options: ['Conduction of water', 'Translocation of food materials, usually from leaves to other parts of the plant', 'Mechanical support only', 'Gaseous exchange'], correctIndex: 1, explanation: 'Phloem is a complex, conducting tissue mainly involved in translocation of food, usually from photosynthetic leaves to other parts.', difficulty: 'easy' },
  { id: 'aofp-25', type: 'mcq', question: 'Which of the following is a living component of phloem in angiosperms?', options: ['Sieve tubes and companion cells', 'Xylem vessels', 'Tracheids', 'Xylem fibres'], correctIndex: 0, explanation: 'Phloem in angiosperms comprises sieve tube elements, companion cells, phloem parenchyma (all living) and phloem fibres (dead); companion cells help load/unload food in sieve elements.', difficulty: 'medium' },
  { id: 'aofp-26', type: 'mcq', question: 'Sieve tube elements are unusual among living cells in that, at maturity, they lack:', options: ['Cell wall', 'A nucleus, though they remain alive', 'Cytoplasm entirely', 'Plasma membrane'], correctIndex: 1, explanation: 'Sieve tube elements are living cells but lose their nucleus at maturity; their functioning is controlled by the adjacent nucleated companion cells.', difficulty: 'medium' },
  { id: 'aofp-27', type: 'mcq', question: 'The end walls of sieve tube elements, perforated with pores through which cytoplasmic strands connect adjacent cells, are called:', options: ['Sieve plates', 'Companion cell walls', 'Casparian strips', 'Middle lamella'], correctIndex: 0, explanation: 'The end walls of sieve tube elements are perforated (sieve plates), and cytoplasmic connections pass through these perforations, connecting the cells.', difficulty: 'medium' },
  { id: 'aofp-28', type: 'mcq', question: 'Companion cells are connected to their adjacent sieve tube elements by:', options: ['Xylem vessels', 'Pit fields/plasmodesmatal connections', 'Sieve plates only', 'No connection exists between them'], correctIndex: 1, explanation: 'Companion cells are specialised parenchyma cells closely associated with sieve tube elements via pit fields, helping maintain the pressure gradient for translocation.', difficulty: 'medium' },
  { id: 'aofp-29', type: 'mcq', question: 'In gymnosperms, conduction of food is carried out by which phloem elements (since companion cells and sieve tubes are absent)?', options: ['Albuminous cells and sieve cells', 'Vessels and tracheids', 'Companion cells only', 'Xylem parenchyma'], correctIndex: 0, explanation: 'Gymnosperms lack companion cells and sieve tubes; instead, they have albuminous cells and sieve cells for food conduction.', difficulty: 'hard' },
  { id: 'aofp-30', type: 'mcq', question: 'Primary phloem, similar to primary xylem, is differentiated into:', options: ['Protophloem and metaphloem', 'Endophloem and exophloem', 'Interfascicular and intrafascicular phloem only', 'Cortical phloem and pith phloem'], correctIndex: 0, explanation: 'Primary phloem that differentiates first is protophloem, and that differentiating later is metaphloem.', difficulty: 'medium' },
  { id: 'aofp-31', type: 'assertion', question: 'Assertion (A): Xylem and phloem are both classified as complex permanent tissues.\nReason (R): Both are made up of more than one type of cell, and all cells coordinate to perform as a single functional unit.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Xylem (tracheids, vessels, fibres, parenchyma) and phloem (sieve elements, companion cells, fibres, parenchyma) both fit the definition of complex tissue given in R.', difficulty: 'medium' },
  { id: 'aofp-32', type: 'assertion', question: 'Assertion (A): Sieve tube elements cannot function independently.\nReason (R): Sieve tube elements lack a nucleus at maturity, and their activities are controlled by the nucleus of the adjoining companion cell.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since sieve tube elements are enucleate, their metabolic activities depend on the nucleus of the associated companion cell, exactly as R states.', difficulty: 'medium' },
  { id: 'aofp-33', type: 'matching', question: 'Match Column I (tissue/cell type) with Column II (characteristic feature):\nColumn I: A. Tracheid  B. Vessel  C. Sieve tube  D. Companion cell\nColumn II: i. Enucleate at maturity  ii. Living, connected to sieve tube via pits  iii. Tapering ends, no perforations  iv. Made of vessel members with perforated walls', options: ['A-iii, B-iv, C-i, D-ii', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-iii, C-ii, D-i', 'A-ii, B-i, C-iv, D-iii'], correctIndex: 0, explanation: 'Tracheid — tapering, no perforations; Vessel — made of perforated vessel members; Sieve tube — enucleate at maturity; Companion cell — living, connected via pits.', difficulty: 'hard' },
  { id: 'aofp-34', type: 'count', question: 'Consider the following statements about xylem and phloem:\n1. Xylem conducts water and minerals and also provides mechanical strength.\n2. Phloem conducts food materials, typically in a bidirectional manner.\n3. All xylem elements are dead at maturity.\n4. All phloem elements are dead at maturity.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 1, explanation: 'Statements 1 and 2 are correct. Statement 3 is wrong (xylem parenchyma is living), and statement 4 is wrong (sieve tubes, companion cells and phloem parenchyma are living).', difficulty: 'hard' },

  // ============ TISSUE SYSTEMS: EPIDERMAL, GROUND, VASCULAR ============
  { id: 'aofp-35', type: 'mcq', question: 'Based on their structure and location, plant tissues are grouped into how many main tissue systems?', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 1, explanation: 'There are three tissue systems in plants: epidermal, ground (fundamental) and vascular tissue systems.', difficulty: 'easy' },
  { id: 'aofp-36', type: 'mcq', question: 'The outermost covering of the plant, made up of a single layer of cells that protects the underlying tissues, constitutes the:', options: ['Vascular tissue system', 'Ground tissue system', 'Epidermal tissue system', 'Meristematic tissue system'], correctIndex: 2, explanation: 'The epidermal tissue system forms the outer protective covering of the plant and consists of epidermal cells, stomata and epidermal appendages (trichomes and hairs).', difficulty: 'easy' },
  { id: 'aofp-37', type: 'mcq', question: 'A waxy, water-resistant layer secreted by epidermal cells that reduces water loss is called:', options: ['Suberin', 'Cutin', 'Lignin', 'Pectin'], correctIndex: 1, explanation: 'Epidermal cells often secrete a waxy, thick layer on their outer surface called the cuticle, made of cutin, which helps prevent water loss.', difficulty: 'medium' },
  { id: 'aofp-38', type: 'mcq', question: 'Stomata are minute pores present mainly in the epidermis of the leaf, each surrounded by two specialised cells called:', options: ['Guard cells', 'Companion cells', 'Subsidiary cells', 'Bulliform cells'], correctIndex: 0, explanation: 'Each stoma is bordered by two bean-shaped or dumb-bell shaped guard cells that regulate its opening and closing, thereby controlling gaseous exchange and transpiration.', difficulty: 'easy' },
  { id: 'aofp-39', type: 'mcq', question: 'In dicot leaves, guard cells are typically ______ in shape, whereas in grasses (monocots), they are typically ______ shaped.', options: ['Dumb-bell; bean', 'Bean; dumb-bell', 'Circular; oval', 'Square; rectangular'], correctIndex: 1, explanation: 'Guard cells are usually bean-shaped in dicots, but in grasses they are dumb-bell shaped.', difficulty: 'medium' },
  { id: 'aofp-40', type: 'mcq', question: 'Root hairs are unicellular epidermal structures whose principal function is:', options: ['Photosynthesis', 'Absorption of water and minerals from the soil', 'Protection from herbivores', 'Gaseous exchange'], correctIndex: 1, explanation: 'Root hairs are unicellular, elongated extensions of epidermal cells that greatly increase the surface area for absorption of water and minerals.', difficulty: 'easy' },
  { id: 'aofp-41', type: 'mcq', question: 'Epidermal hairs on the stem surface, generally multicellular and variously branched, are called:', options: ['Root hairs', 'Trichomes', 'Guard cells', 'Sieve elements'], correctIndex: 1, explanation: 'Trichomes are epidermal appendages on the stem, usually multicellular, and may help reduce water loss due to transpiration.', difficulty: 'medium' },
  { id: 'aofp-42', type: 'mcq', question: 'All tissues located between the epidermis and the vascular tissues, comprising cortex, pericycle, pith and medullary rays, constitute the:', options: ['Epidermal tissue system', 'Ground tissue system', 'Vascular tissue system', 'Meristematic tissue system'], correctIndex: 1, explanation: 'The ground tissue system consists of all tissues excluding the epidermis and vascular bundles — mostly parenchyma, but also collenchyma and sclerenchyma.', difficulty: 'medium' },
  { id: 'aofp-43', type: 'mcq', question: 'The vascular tissue system consists of complex tissues, namely:', options: ['Xylem and phloem', 'Parenchyma and collenchyma', 'Epidermis and cuticle', 'Cortex and pith'], correctIndex: 0, explanation: 'The vascular system consists of xylem and phloem together, forming vascular bundles.', difficulty: 'easy' },
  { id: 'aofp-44', type: 'mcq', question: 'A vascular bundle in which the xylem and phloem are arranged on different radii, alternating with each other, is called:', options: ['Conjoint', 'Radial', 'Collateral', 'Bicollateral'], correctIndex: 1, explanation: 'In a radial vascular bundle (as found in roots), xylem and phloem are arranged separately along different radii, alternating with each other.', difficulty: 'medium' },
  { id: 'aofp-45', type: 'mcq', question: 'A vascular bundle in which xylem and phloem are situated on the same radius, as commonly found in the stem, is called:', options: ['Radial', 'Conjoint', 'Concentric', 'Open collateral only'], correctIndex: 1, explanation: 'In a conjoint vascular bundle, xylem and phloem are jointly situated on the same radius, as typically seen in stems.', difficulty: 'medium' },
  { id: 'aofp-46', type: 'mcq', question: 'A conjoint vascular bundle in which cambium is present between the xylem and phloem, allowing secondary growth, is called:', options: ['Closed', 'Open', 'Radial', 'Concentric'], correctIndex: 1, explanation: 'Open vascular bundles have cambium present between xylem and phloem, permitting secondary growth; these are typical of dicots.', difficulty: 'medium' },
  { id: 'aofp-47', type: 'mcq', question: 'Vascular bundles lacking cambium between xylem and phloem, and thus incapable of secondary growth, are called:', options: ['Open bundles', 'Closed bundles', 'Radial bundles', 'Bicollateral bundles'], correctIndex: 1, explanation: 'Closed vascular bundles lack cambium and cannot undergo secondary growth; these are found in monocots.', difficulty: 'medium' },
  { id: 'aofp-48', type: 'mcq', question: 'A conjoint vascular bundle in which phloem is present on both the inner and outer sides of the xylem is called:', options: ['Collateral', 'Bicollateral', 'Radial', 'Concentric'], correctIndex: 1, explanation: 'Bicollateral vascular bundles have phloem located on both outer and inner sides of the xylem, as found in Cucurbitaceae members.', difficulty: 'hard' },
  { id: 'aofp-49', type: 'matching', question: 'Match Column I (tissue system) with Column II (component/feature):\nColumn I: A. Epidermal tissue system  B. Ground tissue system  C. Vascular tissue system\nColumn II: i. Xylem and phloem  ii. Cortex, pericycle, pith  iii. Guard cells, trichomes, stomata', options: ['A-iii, B-ii, C-i', 'A-i, B-ii, C-iii', 'A-ii, B-iii, C-i', 'A-iii, B-i, C-ii'], correctIndex: 0, explanation: 'Epidermal tissue system — guard cells, trichomes, stomata; Ground tissue system — cortex, pericycle, pith; Vascular tissue system — xylem and phloem.', difficulty: 'medium' },

  // ============ DICOT ROOT ANATOMY ============
  { id: 'aofp-50', type: 'mcq', question: 'In a transverse section of a typical dicot root, the outermost single-layered protective tissue is the:', options: ['Epiblema (piliferous layer)', 'Endodermis', 'Pericycle', 'Cortex'], correctIndex: 0, explanation: 'The outermost layer of the dicot root is the epiblema (piliferous layer), which bears unicellular root hairs and lacks a cuticle.', difficulty: 'easy' },
  { id: 'aofp-51', type: 'mcq', question: 'Just inside the epiblema of a dicot root, a wide region composed largely of thin-walled parenchymatous cells with intercellular spaces is the:', options: ['Cortex', 'Pith', 'Stele', 'Endodermis'], correctIndex: 0, explanation: 'The cortex lies just below the epiblema, is made up of several layers of thin-walled parenchyma cells with intercellular spaces, and helps in the radial conduction of water.', difficulty: 'easy' },
  { id: 'aofp-52', type: 'mcq', question: 'The innermost layer of the cortex, forming a distinct boundary between the cortex and the stele in a dicot root, is called:', options: ['Endodermis', 'Pericycle', 'Epiblema', 'Pith'], correctIndex: 0, explanation: 'The endodermis is the innermost, single-layered boundary of the cortex, characterised by the presence of Casparian strips.', difficulty: 'easy' },
  { id: 'aofp-53', type: 'mcq', question: 'Casparian strips, present in the radial and transverse walls of endodermal cells of the root, are composed of:', options: ['Cellulose and pectin', 'Suberin', 'Lignin only', 'Cutin'], correctIndex: 1, explanation: 'Casparian strips are band-like thickenings of suberin, an impermeable, waxy material, on the radial and transverse walls of endodermal cells.', difficulty: 'medium' },
  { id: 'aofp-54', type: 'mcq', question: 'The layer of cells just inside the endodermis of a root, from which lateral roots and vascular cambium (during secondary growth) arise, is called the:', options: ['Pericycle', 'Cortex', 'Pith', 'Epiblema'], correctIndex: 0, explanation: 'The pericycle, lying just inside the endodermis, gives rise to lateral roots and contributes to the vascular cambium during secondary growth.', difficulty: 'medium' },
  { id: 'aofp-55', type: 'mcq', question: 'In a typical dicot root, the vascular bundles are arranged as:', options: ['Conjoint and scattered throughout the stele', 'Radial, with xylem and phloem on different radii, xylem usually 2 to 4 (polyarch, but limited number)', 'Radial and numerous (polyarch, many arches)', 'A single ring of collateral bundles'], correctIndex: 1, explanation: 'In dicot roots, xylem and phloem bundles are arranged radially, and the number of xylem patches is usually limited (di- to tetrarch, i.e., 2 to 4).', difficulty: 'medium' },
  { id: 'aofp-56', type: 'mcq', question: 'The centre of a typical dicot root is often occupied by:', options: ['A large, well-developed pith', 'Conjunctive tissue with little or no pith, as xylem often extends to the centre', 'A large air cavity', 'Secondary phloem'], correctIndex: 1, explanation: 'In dicot roots, pith is generally poorly developed or absent, as the xylem usually extends up to the centre.', difficulty: 'medium' },
  { id: 'aofp-57', type: 'mcq', question: 'In a dicot root, the tissue lying between the xylem and phloem bundles, which later becomes meristematic during secondary growth, is:', options: ['Conjunctive tissue', 'Casparian strip', 'Endodermis', 'Pith'], correctIndex: 0, explanation: 'Conjunctive tissue (parenchyma) lies between the xylem and phloem in the root; during secondary growth, some of it becomes meristematic to form the vascular cambium.', difficulty: 'medium' },

  // ============ MONOCOT ROOT ANATOMY ============
  { id: 'aofp-58', type: 'mcq', question: 'Compared to a dicot root, the number of xylem bundles (arches) in a typical monocot root is:', options: ['Limited to 2–4 (di- to tetrarch)', 'Usually more than six, i.e., polyarch', 'Always exactly two', 'Absent altogether'], correctIndex: 1, explanation: 'Monocot roots typically show polyarch xylem, with more than six xylem bundles, unlike the limited (di- to tetrarch) number in dicot roots.', difficulty: 'medium' },
  { id: 'aofp-59', type: 'mcq', question: 'A monocot root differs from a dicot root in that the monocot root has a:', options: ['Well-developed, large pith at the centre', 'Poorly developed or absent pith', 'Vascular cambium capable of secondary growth', 'Reduced number of xylem arches (2–4)'], correctIndex: 0, explanation: 'Unlike dicot roots, monocot roots have a well-developed pith at the centre because the xylem does not extend up to the centre.', difficulty: 'medium' },
  { id: 'aofp-60', type: 'mcq', question: 'Which of the following is TRUE regarding secondary growth in monocot roots?', options: ['Monocot roots typically show secondary growth like dicot roots', 'Monocot roots generally do NOT show secondary growth', 'Only the phloem shows secondary growth in monocots', 'Secondary growth occurs only in monocot stems, not roots, which is same as roots'], correctIndex: 1, explanation: 'Monocot roots generally do not show secondary growth, as they lack a functional vascular cambium between xylem and phloem.', difficulty: 'medium' },
  { id: 'aofp-61', type: 'assertion', question: 'Assertion (A): The number of xylem arches helps distinguish monocot roots from dicot roots.\nReason (R): Monocot roots are typically polyarch (more than six xylem bundles), while dicot roots are usually di- to tetrarch (2 to 4 xylem bundles).', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The difference in the number of xylem arches, exactly as described in R, is a key anatomical feature used to distinguish monocot and dicot roots.', difficulty: 'medium' },
  { id: 'aofp-62', type: 'count', question: 'Consider the following features of a typical monocot root:\n1. Polyarch xylem (more than six bundles).\n2. Well-developed pith at the centre.\n3. Presence of vascular cambium enabling secondary growth.\n4. Epiblema with unicellular root hairs.\nHow many of the above statements are correct for a monocot root?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct features of monocot roots. Statement 3 is incorrect — monocot roots lack vascular cambium and generally do not undergo secondary growth.', difficulty: 'hard' },

  // ============ DICOT STEM ANATOMY ============
  { id: 'aofp-63', type: 'mcq', question: 'In a transverse section of a typical dicot stem, the outermost layer, often covered by a cuticle and generally lacking stomata except in young stems, is the:', options: ['Epidermis', 'Cortex', 'Pericycle', 'Endodermis'], correctIndex: 0, explanation: 'The epidermis of the stem is the outermost protective layer, generally covered by a cuticle, with occasional stomata and trichomes.', difficulty: 'easy' },
  { id: 'aofp-64', type: 'mcq', question: 'The cortex of a dicot stem, situated below the epidermis, is often differentiated into three sub-zones. Which of the following is the correct sequence from outside to inside?', options: ['Hypodermis (collenchymatous) → general cortex (parenchymatous) → endodermis (starch sheath)', 'Endodermis → general cortex → hypodermis', 'Pericycle → hypodermis → endodermis', 'General cortex → pericycle → hypodermis'], correctIndex: 0, explanation: 'In dicot stems, the cortex is differentiated into an outer hypodermis (collenchymatous, providing mechanical support), a middle general cortex (parenchymatous), and an inner endodermis, often rich in starch (starch sheath).', difficulty: 'medium' },
  { id: 'aofp-65', type: 'mcq', question: 'The innermost layer of the cortex in a dicot stem, typically rich in starch grains, is referred to as the:', options: ['Hypodermis', 'Starch sheath (endodermis)', 'Pericycle', 'Pith'], correctIndex: 1, explanation: 'The innermost cortical layer in dicot stems is generally rich in starch grains and is termed the starch sheath, considered equivalent to the endodermis.', difficulty: 'medium' },
  { id: 'aofp-66', type: 'mcq', question: 'In dicot stems, the vascular bundles are typically arranged as:', options: ['Scattered throughout the ground tissue', 'A ring around the central pith, conjoint, collateral and open', 'Radial, similar to the root', 'Absent altogether'], correctIndex: 1, explanation: 'In dicot stems, vascular bundles are conjoint, collateral and open, and are arranged in a ring around a well-developed central pith.', difficulty: 'medium' },
  { id: 'aofp-67', type: 'mcq', question: 'The band of meristematic cells present between the xylem and phloem in an open vascular bundle of a dicot stem is called:', options: ['Pericycle', 'Cambium', 'Pith', 'Cortex'], correctIndex: 1, explanation: 'In open vascular bundles, cambium is present between xylem and phloem and is responsible for secondary growth.', difficulty: 'easy' },
  { id: 'aofp-68', type: 'mcq', question: 'In a dicot stem, the region occupied by large, parenchymatous cells at the very centre, often used for food storage, is the:', options: ['Cortex', 'Pith', 'Endodermis', 'Pericycle'], correctIndex: 1, explanation: 'The pith occupies the central part of the stem and is composed of large, parenchymatous cells, sometimes with intercellular spaces.', difficulty: 'easy' },
  { id: 'aofp-69', type: 'mcq', question: 'The narrow parenchymatous strips connecting the pith and cortex in between vascular bundles of a dicot stem are called:', options: ['Medullary rays', 'Casparian strips', 'Bundle sheaths', 'Endodermal strips'], correctIndex: 0, explanation: 'Medullary (pith) rays are narrow strips of parenchyma present between adjacent vascular bundles, connecting the pith with the cortex.', difficulty: 'medium' },

  // ============ MONOCOT STEM ANATOMY ============
  { id: 'aofp-70', type: 'mcq', question: 'In a typical monocot stem, the ground tissue is NOT differentiated into cortex, endodermis, pericycle, pith and medullary rays; instead, the vascular bundles are:', options: ['Arranged in a single ring', 'Scattered throughout the ground tissue', 'Absent altogether', 'Arranged radially, as in roots'], correctIndex: 1, explanation: 'In monocot stems, numerous vascular bundles are scattered throughout the ground tissue instead of being arranged in a ring.', difficulty: 'medium' },
  { id: 'aofp-71', type: 'mcq', question: 'The hypodermis of a monocot stem, in contrast to that of a dicot stem, is typically made of:', options: ['Collenchyma', 'Sclerenchyma', 'Parenchyma only', 'Meristematic tissue'], correctIndex: 1, explanation: 'The hypodermis in a monocot stem is generally sclerenchymatous, unlike the collenchymatous hypodermis of a dicot stem.', difficulty: 'medium' },
  { id: 'aofp-72', type: 'mcq', question: 'Each vascular bundle in a monocot stem is typically surrounded by a sclerenchymatous covering called the:', options: ['Bundle sheath', 'Endodermis', 'Cambium ring', 'Cortex'], correctIndex: 0, explanation: 'Vascular bundles in monocot stems are conjoint, collateral, closed, and each bundle is surrounded by a sclerenchymatous bundle sheath.', difficulty: 'medium' },
  { id: 'aofp-73', type: 'mcq', question: 'Vascular bundles in a monocot stem are closed, which means:', options: ['They are enclosed by a bundle sheath and lack cambium, so secondary growth does not occur', 'They contain both xylem and phloem on different radii', 'They are surrounded by pith', 'They contain cambium and undergo secondary growth'], correctIndex: 0, explanation: 'Closed vascular bundles lack cambium, so they cannot form secondary tissue; hence monocot stems generally do not show secondary growth.', difficulty: 'medium' },
  { id: 'aofp-74', type: 'mcq', question: 'The xylem vessels in a monocot vascular bundle are often arranged in which characteristic shape?', options: ['V-shaped or Y-shaped', 'A straight line', 'A circle', 'A cross'], correctIndex: 0, explanation: 'In monocot vascular bundles, xylem vessels are usually arranged in a V-shaped or Y-shaped pattern, with the presence of water-containing cavities.', difficulty: 'hard' },
  { id: 'aofp-75', type: 'mcq', question: 'Large, water-storing cavities found within the xylem of some monocot vascular bundles are called:', options: ['Water cavities/lysigenous cavities', 'Air chambers', 'Resin ducts', 'Latex canals'], correctIndex: 0, explanation: 'In some monocot vascular bundles (e.g., maize), water-containing cavities are present due to the disintegration of protoxylem elements.', difficulty: 'hard' },
  { id: 'aofp-76', type: 'assertion', question: 'Assertion (A): Monocot stems generally do not undergo secondary growth.\nReason (R): The vascular bundles of monocot stems are closed, lacking cambium between xylem and phloem.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'The absence of cambium in closed vascular bundles (R) directly explains why monocot stems typically lack secondary growth (A).', difficulty: 'medium' },
  { id: 'aofp-77', type: 'matching', question: 'Match Column I (feature) with Column II (dicot stem/monocot stem):\nColumn I: A. Vascular bundles in a ring  B. Vascular bundles scattered  C. Open vascular bundles  D. Closed vascular bundles\nColumn II: i. Monocot stem  ii. Dicot stem  iii. Dicot stem  iv. Monocot stem', options: ['A-ii, B-i, C-iii, D-iv', 'A-i, B-ii, C-iv, D-iii', 'A-ii, B-iv, C-i, D-iii', 'A-iii, B-iv, C-ii, D-i'], correctIndex: 0, explanation: 'Ring arrangement and open bundles are dicot stem features; scattered arrangement and closed bundles are monocot stem features.', difficulty: 'medium' },

  // ============ DICOT LEAF ANATOMY ============
  { id: 'aofp-78', type: 'mcq', question: 'A dicotyledonous leaf, when cut vertically, shows three main parts: epidermis, mesophyll and:', options: ['Vascular system', 'Pith', 'Cortex', 'Pericycle'], correctIndex: 0, explanation: 'A dicot leaf in vertical section shows three main parts — epidermis, mesophyll and vascular system.', difficulty: 'easy' },
  { id: 'aofp-79', type: 'mcq', question: 'The epidermis of a dicot leaf is present on both surfaces; the epidermis in contact with the upper surface is called the:', options: ['Abaxial epidermis', 'Adaxial epidermis', 'Endodermis', 'Bundle sheath'], correctIndex: 1, explanation: 'The upper epidermis of the leaf is called adaxial, while the lower epidermis (facing away from the stem/axis) is called abaxial.', difficulty: 'medium' },
  { id: 'aofp-80', type: 'mcq', question: 'The tissue between the upper and lower epidermis of a leaf, containing chloroplasts and responsible for photosynthesis, is called:', options: ['Mesophyll', 'Bundle sheath', 'Hypodermis', 'Pith'], correctIndex: 0, explanation: 'The mesophyll tissue, located between the two epidermal layers, possesses chloroplasts and carries out photosynthesis.', difficulty: 'easy' },
  { id: 'aofp-81', type: 'mcq', question: 'In a typical dorsiventral (dicot) leaf, the mesophyll is differentiated into palisade parenchyma and spongy parenchyma. The palisade parenchyma is located:', options: ['Towards the lower (abaxial) epidermis', 'Towards the upper (adaxial) epidermis, made of elongated cells', 'In the centre of the leaf only', 'Surrounding the vascular bundles only'], correctIndex: 1, explanation: 'In dicot leaves, palisade parenchyma is present on the upper (adaxial) side, consisting of elongated cells arranged vertically, while spongy parenchyma with air spaces lies below, towards the lower epidermis.', difficulty: 'medium' },
  { id: 'aofp-82', type: 'mcq', question: 'Vascular bundles in the leaf are surrounded by a layer of thick-walled cells called the:', options: ['Bundle sheath', 'Endodermis', 'Pericycle', 'Hypodermis'], correctIndex: 0, explanation: 'Each vascular bundle in a leaf is surrounded by a layer (or several layers) of compactly arranged cells known as the bundle sheath.', difficulty: 'medium' },
  { id: 'aofp-83', type: 'mcq', question: 'A dorsiventral leaf, typically found in dicots, has stomata:', options: ['Equally distributed on both surfaces', 'More numerous on the lower (abaxial) surface than the upper', 'Present only on the upper surface', 'Completely absent from the leaf surface'], correctIndex: 1, explanation: 'In a dorsiventral leaf, stomata are usually more numerous on the lower surface than the upper surface, minimising water loss from the sun-facing surface.', difficulty: 'medium' },

  // ============ MONOCOT LEAF ANATOMY ============
  { id: 'aofp-84', type: 'mcq', question: 'A monocot (isobilateral) leaf differs from a dicot leaf in that its mesophyll is:', options: ['Differentiated into palisade and spongy parenchyma', 'Not differentiated into palisade and spongy tissue', 'Absent altogether', 'Made entirely of sclerenchyma'], correctIndex: 1, explanation: 'In an isobilateral monocot leaf, the mesophyll is not differentiated into palisade and spongy parenchyma, and both surfaces appear similar.', difficulty: 'medium' },
  { id: 'aofp-85', type: 'mcq', question: 'Stomata are usually distributed almost equally on both surfaces in which type of leaf?', options: ['Dorsiventral (dicot) leaf', 'Isobilateral (monocot) leaf', 'Compound leaf only', 'Simple leaf only'], correctIndex: 1, explanation: 'In isobilateral leaves (common in monocots such as grasses), stomata are distributed nearly equally on both leaf surfaces.', difficulty: 'medium' },
  { id: 'aofp-86', type: 'mcq', question: 'Large, empty, colourless cells present in the upper epidermis of grass leaves, involved in leaf rolling/unrolling during water stress, are called:', options: ['Guard cells', 'Bulliform cells', 'Companion cells', 'Subsidiary cells'], correctIndex: 1, explanation: 'Bulliform cells are large, vacuolated, thin-walled cells present on the upper epidermis of many monocot (grass) leaves; they help the leaf roll inward during water scarcity to minimise transpiration.', difficulty: 'medium' },
  { id: 'aofp-87', type: 'assertion', question: 'Assertion (A): Grass leaves can curl during periods of water scarcity.\nReason (R): Bulliform cells located in the upper epidermis lose turgidity under water stress, causing the leaf to roll inwards and reduce the transpiring surface.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Loss of turgidity in bulliform cells causes leaf rolling, which reduces the exposed transpiring surface, correctly explaining the assertion.', difficulty: 'medium' },
  { id: 'aofp-88', type: 'count', question: 'Consider the following statements comparing dicot and monocot leaves:\n1. Dicot leaves are dorsiventral, while monocot leaves are typically isobilateral.\n2. In dicot leaves, mesophyll is differentiated into palisade and spongy tissue; in isobilateral monocot leaves it usually is not.\n3. Bulliform cells are typically found in monocot (grass) leaves and help in leaf rolling.\n4. Stomata are always absent from the upper surface of monocot leaves.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is wrong — in isobilateral monocot leaves, stomata are present on both surfaces, roughly equally.', difficulty: 'hard' },

  // ============ SECONDARY GROWTH ============
  { id: 'aofp-89', type: 'mcq', question: 'The increase in girth of the stem and root due to the activity of lateral meristems is called:', options: ['Primary growth', 'Secondary growth', 'Intercalary growth', 'Apical growth'], correctIndex: 1, explanation: 'Secondary growth refers to an increase in girth (diameter) of stems and roots due to the activity of lateral meristems — vascular cambium and cork cambium.', difficulty: 'easy' },
  { id: 'aofp-90', type: 'mcq', question: 'In a dicot stem, secondary growth begins with the formation of a complete ring of cambium, which forms by the joining of:', options: ['Intrafascicular cambium (within vascular bundles) and interfascicular cambium (formed from medullary ray cells)', 'Cork cambium and phellogen only', 'Endodermis and pericycle', 'Xylem and phloem parenchyma only'], correctIndex: 0, explanation: 'A complete ring of vascular cambium is formed by the intrafascicular cambium (present within vascular bundles) joining with the interfascicular cambium, which develops from the medullary ray cells adjoining the fascicular cambium.', difficulty: 'medium' },
  { id: 'aofp-91', type: 'mcq', question: 'During secondary growth, the vascular cambium ring cuts off new cells on both sides. Which of the following is correct?', options: ['Secondary xylem is cut off towards the outside and secondary phloem towards the inside', 'Secondary xylem is cut off towards the inside and secondary phloem towards the outside', 'Both secondary xylem and phloem are cut off only towards the outside', 'Neither xylem nor phloem is formed during secondary growth'], correctIndex: 1, explanation: 'The cambium ring cuts off new cells, adding secondary xylem towards the inner side (pith side) and secondary phloem towards the outer side (cortex side).', difficulty: 'medium' },
  { id: 'aofp-92', type: 'mcq', question: 'Due to unequal activity of the vascular cambium in different seasons, alternating bands of xylem are formed, giving rise to:', options: ['Growth rings (annual rings)', 'Medullary rays only', 'Bark', 'Lenticels'], correctIndex: 0, explanation: 'Unequal cambial activity in different seasons produces alternating layers of xylem with different characteristics, seen as growth/annual rings in a cross-section of the stem.', difficulty: 'medium' },
  { id: 'aofp-93', type: 'mcq', question: 'The wood formed during spring, which is lighter in colour and has larger xylem vessels due to abundant water availability, is called:', options: ['Autumn wood (late wood)', 'Spring wood (early wood)', 'Heartwood', 'Sapwood'], correctIndex: 1, explanation: 'Spring wood (early wood) is formed in the spring season, has larger and more numerous vessels, and is lighter in colour and lower in density than autumn wood.', difficulty: 'medium' },
  { id: 'aofp-94', type: 'mcq', question: 'The central, non-functional, darker region of secondary xylem in an old tree trunk, which no longer conducts water but provides mechanical support, is called:', options: ['Sapwood', 'Heartwood', 'Cork', 'Cambium'], correctIndex: 1, explanation: 'Heartwood is the dark-coloured, central wood filled with tannins, resins and other substances that make it durable but non-functional in water conduction.', difficulty: 'medium' },
  { id: 'aofp-95', type: 'mcq', question: 'The peripheral, lighter-coloured region of secondary xylem in an old tree trunk that actively conducts water and minerals is called:', options: ['Heartwood', 'Sapwood', 'Bark', 'Cork'], correctIndex: 1, explanation: 'Sapwood (alburnum) is the peripheral wood, usually lighter in colour, that is still active in water conduction.', difficulty: 'medium' },
  { id: 'aofp-96', type: 'mcq', question: 'The formation of cork cambium (phellogen) in the cortex region of a dicot stem is part of which developmental process?', options: ['Primary growth', 'Secondary growth of the stem covering (periderm formation)', 'Root growth', 'Leaf abscission'], correctIndex: 1, explanation: 'As the stem increases in girth, the outer cortex layers rupture, and a phellogen (cork cambium) develops, leading to the formation of periderm (secondary protective tissue) replacing the epidermis.', difficulty: 'medium' },
  { id: 'aofp-97', type: 'mcq', question: 'The cork cambium (phellogen) cuts off cells on both sides; cells cut off towards the outside differentiate into cork (phellem), while cells cut off towards the inside form:', options: ['Secondary cortex (phelloderm)', 'Secondary xylem', 'Pith', 'Bundle sheath'], correctIndex: 0, explanation: 'Phellogen produces phellem (cork) towards the outside and phelloderm (secondary cortex) towards the inside; together phellogen, phellem and phelloderm constitute the periderm.', difficulty: 'medium' },
  { id: 'aofp-98', type: 'mcq', question: 'Cork cells are impervious to water and gases because their walls are heavily deposited with:', options: ['Lignin', 'Suberin', 'Cellulose', 'Cutin'], correctIndex: 1, explanation: 'Cork cells are dead, compactly arranged, and their walls have suberin deposited, making them impermeable to water and gases.', difficulty: 'medium' },
  { id: 'aofp-99', type: 'mcq', question: 'Small pores present in the cork/bark that facilitate gaseous exchange between the internal tissues of the stem and the outer atmosphere are called:', options: ['Stomata', 'Lenticels', 'Hydathodes', 'Trichomes'], correctIndex: 1, explanation: 'Lenticels are small openings in the bark/cork that allow exchange of gases between internal tissues and the atmosphere.', difficulty: 'medium' },
  { id: 'aofp-100', type: 'mcq', question: 'The term "bark" refers to:', options: ['Only the cork tissue of a stem', 'All the tissues external to the vascular cambium in a mature woody stem', 'Only the vascular cambium', 'Only the pith and cortex'], correctIndex: 1, explanation: 'Bark is a non-technical term used to describe all tissues external to the vascular cambium (secondary phloem, cortex, periderm) in a woody stem.', difficulty: 'medium' },
  { id: 'aofp-101', type: 'assertion', question: 'Assertion (A): Growth (annual) rings can be used to estimate the approximate age of a tree.\nReason (R): Vascular cambium shows differential activity in different seasons, producing distinct alternating bands of spring wood and autumn wood each year.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since one growth ring (spring wood + autumn wood band) generally forms per year due to seasonal cambial activity, counting rings gives an estimate of tree age, exactly as explained by R.', difficulty: 'medium' },
  { id: 'aofp-102', type: 'matching', question: 'Match Column I (term) with Column II (description):\nColumn I: A. Phellogen  B. Phellem  C. Phelloderm  D. Lenticel\nColumn II: i. Secondary cortex formed inward  ii. Cork cambium  iii. Pore for gaseous exchange in bark  iv. Cork formed outward', options: ['A-ii, B-iv, C-i, D-iii', 'A-i, B-ii, C-iii, D-iv', 'A-iv, B-ii, C-iii, D-i', 'A-ii, B-i, C-iv, D-iii'], correctIndex: 0, explanation: 'Phellogen — cork cambium; Phellem — cork (formed outward); Phelloderm — secondary cortex (formed inward); Lenticel — pore for gas exchange.', difficulty: 'hard' },
  { id: 'aofp-103', type: 'count', question: 'Consider the following statements about secondary growth:\n1. Secondary growth is brought about by the vascular cambium and cork cambium.\n2. In dicot roots, secondary growth starts with cambium forming initially in strips just below the phloem bundles.\n3. Monocot stems generally show extensive secondary growth similar to dicot stems.\n4. Growth rings result from seasonal variation in cambial activity.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 4 are correct. Statement 3 is wrong — monocot stems generally lack secondary growth due to closed vascular bundles.', difficulty: 'hard' },

  // ============ SECONDARY GROWTH IN ROOTS ============
  { id: 'aofp-104', type: 'mcq', question: 'In dicot roots, the vascular cambium initially develops as discontinuous patches, appearing just below the:', options: ['Phloem bundles, on the inner side', 'Epiblema', 'Pith', 'Endodermis, away from the phloem'], correctIndex: 0, explanation: 'In a dicot root, the cambium first appears as single-layered patches just below each phloem group, on the inner side.', difficulty: 'hard' },
  { id: 'aofp-105', type: 'mcq', question: 'In the secondary growth of a dicot root, the pericycle cells lying just above the protoxylem also become meristematic. This ultimately results in the cambium ring becoming:', options: ['Highly irregular in shape only near the xylem', 'Wavy at first, then eventually circular', 'Absent altogether', 'Restricted only to the phloem side'], correctIndex: 1, explanation: 'The cambium formed from the conjunctive tissue (near phloem) plus pericycle cells (near protoxylem) initially forms a wavy ring, which later becomes circular in outline.', difficulty: 'hard' },

  // ============ DIFFERENCES / COMPARATIVE ANATOMY ============
  { id: 'aofp-106', type: 'mcq', question: 'Which of the following features is typically used to distinguish a dicot stem from a monocot stem in transverse section?', options: ['Presence of vascular bundles in a ring versus scattered arrangement', 'Presence of xylem and phloem versus their absence', 'Presence of epidermis versus its absence', 'Presence of cell wall versus its absence'], correctIndex: 0, explanation: 'A dicot stem has vascular bundles arranged in a ring with distinct cortex/pith, while a monocot stem has bundles scattered throughout the ground tissue.', difficulty: 'easy' },
  { id: 'aofp-107', type: 'mcq', question: 'Which of the following is characteristic of BOTH dicot and monocot roots?', options: ['Presence of epiblema (piliferous layer) bearing root hairs', 'Presence of a well-developed pith at the centre', 'Presence of secondary growth', 'Presence of xylem in a V-shaped pattern'], correctIndex: 0, explanation: 'Both monocot and dicot roots have an outer epiblema bearing unicellular root hairs, although they differ in xylem arch number, pith development and secondary growth.', difficulty: 'medium' },
  { id: 'aofp-108', type: 'count', question: 'Consider the following comparative statements between dicot and monocot roots:\n1. Dicot roots are typically di- to tetrarch; monocot roots are polyarch.\n2. Dicot roots have poorly developed pith; monocot roots have well-developed pith.\n3. Dicot roots undergo secondary growth; monocot roots generally do not.\n4. Both dicot and monocot roots possess an epiblema with root hairs.\nHow many of these comparative statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 3, explanation: 'All four statements correctly summarise the anatomical differences and similarities between dicot and monocot roots.', difficulty: 'medium' },
  { id: 'aofp-109', type: 'count', question: 'Consider the following comparative statements between dicot and monocot stems:\n1. Dicot stem hypodermis is collenchymatous; monocot stem hypodermis is sclerenchymatous.\n2. Dicot stem has open vascular bundles; monocot stem has closed vascular bundles.\n3. Dicot stem vascular bundles are arranged in a ring; monocot stem bundles are scattered.\n4. Dicot stem has bundle sheaths around each vascular bundle, but monocot stem does not.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is incorrect — it is the monocot stem, not the dicot stem, whose vascular bundles are typically surrounded by a sclerenchymatous bundle sheath.', difficulty: 'hard' },
  { id: 'aofp-110', type: 'matching', question: 'Match Column I (structure) with Column II (found predominantly in):\nColumn I: A. Polyarch xylem  B. Well-developed pith in root  C. Open vascular bundles  D. Bulliform cells\nColumn II: i. Monocot stem  ii. Monocot root  iii. Dicot stem  iv. Monocot leaf', options: ['A-ii, B-ii, C-iii, D-iv', 'A-ii, B-iii, C-iv, D-i', 'A-iii, B-i, C-ii, D-iv', 'A-i, B-ii, C-iii, D-iv'], correctIndex: 0, explanation: 'Polyarch xylem and well-developed pith are monocot root features; open vascular bundles are dicot stem features; bulliform cells occur in monocot leaves.', difficulty: 'hard' },

  // ============ MIXED / REVISION ============
  { id: 'aofp-111', type: 'mcq', question: 'Which of the following cell types is classified under simple permanent tissue?', options: ['Xylem', 'Phloem', 'Parenchyma', 'Vascular bundle'], correctIndex: 2, explanation: 'Parenchyma, collenchyma and sclerenchyma are simple permanent tissues, made of only one type of cell, unlike complex tissues such as xylem and phloem.', difficulty: 'easy' },
  { id: 'aofp-112', type: 'mcq', question: 'Storage of starch, protein and other substances is a major function of which simple tissue, especially in roots and storage organs?', options: ['Sclerenchyma', 'Parenchyma', 'Collenchyma', 'Xylem fibres'], correctIndex: 1, explanation: 'Parenchyma cells often store various substances such as starch, oils and tannins in roots, stems and other storage organs.', difficulty: 'easy' },
  { id: 'aofp-113', type: 'mcq', question: 'The hard, stony texture of the endocarp in coconut and the gritty texture of guava/pear pulp are both due to the presence of:', options: ['Collenchyma cells', 'Sclereids', 'Xylem vessels', 'Parenchyma with chloroplasts'], correctIndex: 1, explanation: 'Sclereids (a type of sclerenchyma) are short, irregular, heavily lignified cells that give hardness/grittiness, e.g., in guava pulp and the hard shell of coconut.', difficulty: 'medium' },
  { id: 'aofp-114', type: 'mcq', question: 'Which of the following is a correct statement about meristematic cells?', options: ['They possess large vacuoles and thick secondary walls', 'They are generally isodiametric, with dense cytoplasm, prominent nuclei, and thin cellulose walls', 'They are always dead at maturity', 'They lack a nucleus'], correctIndex: 1, explanation: 'Meristematic cells are typically isodiametric with dense cytoplasm, prominent nuclei, thin cellulose walls, and usually lack vacuoles.', difficulty: 'medium' },
  { id: 'aofp-115', type: 'mcq', question: 'Water in xylem is conducted from cell to cell primarily through structures called:', options: ['Sieve plates', 'Pits', 'Companion cell connections', 'Plasmodesmata of the phloem'], correctIndex: 1, explanation: 'In tracheids (and to conduct laterally in vessels too), water passes from cell to cell through pits present in the cell walls.', difficulty: 'medium' },
  { id: 'aofp-116', type: 'mcq', question: 'Which of the following statements correctly distinguishes tracheids from vessels?', options: ['Tracheids have perforated end walls; vessels do not', 'Vessels are formed by fusion of several cells (vessel members) with perforated end walls; tracheids are single elongated cells without perforations', 'Tracheids are found only in angiosperms; vessels are found only in gymnosperms', 'There is no structural difference between tracheids and vessels'], correctIndex: 1, explanation: 'Vessels are multicellular tubes formed by the fusion of vessel members with perforated end walls, enabling more efficient conduction than tracheids, which are single, imperforate, elongated cells.', difficulty: 'medium' },
  { id: 'aofp-117', type: 'mcq', question: 'The stomatal apparatus, consisting of guard cells along with the surrounding subsidiary cells, is part of which tissue system?', options: ['Vascular tissue system', 'Ground tissue system', 'Epidermal tissue system', 'Meristematic tissue system'], correctIndex: 2, explanation: 'Stomata, along with guard cells and subsidiary cells, are components of the epidermal tissue system.', difficulty: 'easy' },
  { id: 'aofp-118', type: 'mcq', question: 'Which combination correctly represents the layers of periderm, from outside to inside?', options: ['Phelloderm → phellogen → phellem', 'Phellem → phellogen → phelloderm', 'Phellogen → phellem → phelloderm', 'Phelloderm → phellem → phellogen'], correctIndex: 1, explanation: 'From the outside inward, periderm consists of phellem (cork), then phellogen (cork cambium), and then phelloderm (secondary cortex).', difficulty: 'hard' },
  { id: 'aofp-119', type: 'mcq', question: 'The term "anomalous secondary growth" refers to secondary growth that:', options: ['Occurs in a manner different from the usual pattern seen in typical dicot stems, e.g., in Boerhaavia and Dracaena', 'Never occurs in nature', 'Is restricted only to roots', 'Occurs only in monocot leaves'], correctIndex: 0, explanation: 'Anomalous secondary growth refers to patterns of secondary growth that deviate from the usual dicot stem pattern, seen in some plants like Boerhaavia and members of the family with extra cambial rings.', difficulty: 'hard' },
  { id: 'aofp-120', type: 'mcq', question: 'Which tissue in the plant body is primarily responsible for both increase in girth AND, when it is cork cambium, for the formation of the protective periderm layer?', options: ['Apical meristem', 'Lateral meristem', 'Intercalary meristem', 'Ground meristem'], correctIndex: 1, explanation: 'Lateral meristems (vascular cambium and cork cambium) are together responsible for secondary growth — increase in girth and formation of periderm.', difficulty: 'medium' },
  { id: 'aofp-121', type: 'count', question: 'Consider the following statements about tissue systems and their roles:\n1. Epidermal tissue system forms the outer protective covering.\n2. Ground tissue system includes cortex, pericycle, pith and medullary rays.\n3. Vascular tissue system is responsible for conduction of water and food.\n4. Meristematic tissue is a type of ground tissue system.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 2 and 3 are correct. Statement 4 is incorrect — meristematic tissue is a separate category based on cell division capacity and is not classified as part of the ground tissue system.', difficulty: 'hard' },
  { id: 'aofp-122', type: 'assertion', question: 'Assertion (A): The pith is generally well developed in monocot stems but poorly developed or absent in dicot roots.\nReason (R): In dicot roots, the xylem usually extends to the very centre of the root, leaving little or no space for pith.', options: ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'], correctIndex: 0, explanation: 'Since xylem extends to the centre in dicot roots, little/no pith remains, correctly explaining why pith is poorly developed there (unlike in monocot stems).', difficulty: 'medium' },
  { id: 'aofp-123', type: 'mcq', question: 'The pattern of secondary growth in dicot stems occurs due to the coordinated activity of:', options: ['Only apical meristem', 'Vascular cambium and cork cambium (both lateral meristems)', 'Only intercalary meristem', 'Only the pericycle'], correctIndex: 1, explanation: 'Secondary growth in dicot stems and roots is due to the combined activity of two lateral meristems — vascular cambium (forms secondary xylem/phloem) and cork cambium (forms periderm).', difficulty: 'medium' },
  { id: 'aofp-124', type: 'mcq', question: 'In an old dicot stem, the primary cortex and epidermis are eventually replaced by which protective tissue?', options: ['Periderm (cork)', 'Pith', 'Secondary xylem', 'Vascular cambium'], correctIndex: 0, explanation: 'As secondary growth proceeds, the epidermis and outer cortex layers rupture and are gradually replaced by the periderm (cork tissue).', difficulty: 'medium' },
  { id: 'aofp-125', type: 'mcq', question: 'Which of the following correctly describes the sequence of tissue layers from outside to inside in a young dicot stem (before secondary growth)?', options: ['Epidermis → hypodermis → general cortex → endodermis → pericycle → vascular bundles → pith', 'Pith → vascular bundles → pericycle → endodermis → cortex → epidermis', 'Epidermis → pith → cortex → vascular bundles', 'Endodermis → epidermis → cortex → pith → vascular bundles'], correctIndex: 0, explanation: 'The correct sequence from outside to inside in a young dicot stem is: epidermis, hypodermis, general cortex, endodermis (starch sheath), pericycle, vascular bundles arranged in a ring, and central pith.', difficulty: 'hard' },
  { id: 'aofp-126', type: 'mcq', question: 'The correct sequence of tissue layers from outside to inside in a typical dicot root (before secondary growth) is:', options: ['Epiblema → cortex → endodermis → pericycle → vascular tissue (radial)', 'Pericycle → endodermis → cortex → epiblema', 'Epiblema → pericycle → cortex → endodermis', 'Endodermis → epiblema → cortex → pericycle'], correctIndex: 0, explanation: 'From outside to inside, a dicot root shows: epiblema (piliferous layer), cortex, endodermis, pericycle, and the central radial vascular tissue (limited xylem and phloem bundles).', difficulty: 'hard' },
  { id: 'aofp-127', type: 'mcq', question: 'The main function of medullary rays in a dicot stem is to:', options: ['Conduct materials radially between the pith and cortex', 'Conduct food only in a longitudinal direction', 'Provide mechanical strength exclusively', 'Produce pollen grains'], correctIndex: 0, explanation: 'Medullary rays are parenchymatous strips that facilitate radial conduction of water and food between the pith and the cortex.', difficulty: 'medium' },
  { id: 'aofp-128', type: 'mcq', question: 'Which of the following statements about companion cells is INCORRECT?', options: ['They are living, specialised parenchyma cells', 'They are closely associated with sieve tube elements', 'They help load and unload food materials in sieve tubes', 'They lack a nucleus, similar to sieve tube elements'], correctIndex: 3, explanation: 'Unlike sieve tube elements, companion cells retain their nucleus and dense cytoplasm; the nucleus of the companion cell controls the functioning of the associated sieve tube element.', difficulty: 'medium' },
  { id: 'aofp-129', type: 'mcq', question: 'Which tissue system provides the greatest bulk of the plant body and includes tissues like cortex, pericycle, medullary rays and pith?', options: ['Epidermal tissue system', 'Ground tissue system', 'Vascular tissue system', 'Meristematic tissue system'], correctIndex: 1, explanation: 'The ground tissue system, made largely of parenchyma along with some collenchyma and sclerenchyma, forms the bulk of the plant body, excluding epidermis and vascular tissue.', difficulty: 'easy' },
  { id: 'aofp-130', type: 'mcq', question: 'Which of the following best explains why xylem vessels are more efficient at water conduction than tracheids?', options: ['Vessels are shorter than tracheids', 'Vessels have perforated end walls forming continuous tubes, allowing more direct flow of water compared to pit-mediated transfer in tracheids', 'Vessels lack lignified walls, unlike tracheids', 'Vessels are living cells while tracheids are dead'], correctIndex: 1, explanation: 'Because vessel members are joined end to end with perforated walls, water flows more freely through a continuous tube, unlike tracheids, where water must pass through pits from cell to cell.', difficulty: 'hard' },
  { id: 'aofp-131', type: 'count', question: 'Consider the following statements about the vascular cambium and its activity:\n1. Vascular cambium is a lateral meristem responsible for secondary growth.\n2. It cuts off secondary phloem towards the inner side and secondary xylem towards the outer side.\n3. Its activity is generally more in spring, producing wider vessels (spring wood).\n4. Growth rings can be used to estimate the age of a tree.\nHow many of the above statements are correct?', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Statements 1, 3 and 4 are correct. Statement 2 is reversed — secondary xylem is cut off towards the inner side and secondary phloem towards the outer side.', difficulty: 'hard' },
];
